def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    bg = max(range(10), key=lambda c: sum(v == c for row in grid for v in row))
    for r in range(h):
        for c in range(1, w - 1):
            if grid[r][c] == bg and grid[r][c - 1] == grid[r][c + 1] and grid[r][c - 1] != bg:
                out[r][c] = 2
    return out
